#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>

const int MAXN = 50;
const int MAXM = 50;
const int MAXK = 50;
const int T = MAXN + MAXK + 1;
const int N_ = MAXN * T + 1;
const int M_ = MAXK + (MAXM * 2 * MAXK + MAXN) * (T - 1);
const int INF = 0x3f3f3f3f;

int dist[N_], parent_kk[N_], parent_bb[N_];
int heap[1 + N_], index_in_heap[N_], heap_size;

int get_next_index(int i) {
    i <<= 1;
    if (i > heap_size) return 0;
    if (i < heap_size && (dist[heap[i + 1]] < dist[heap[i]] || (dist[heap[i + 1]] == dist[heap[i]] && parent_kk[heap[i + 1]] < parent_kk[heap[i]]))) return i + 1;
    return i;
}

void heapify_up(int u) {
    int i = index_in_heap[u], j;
    while (i > 1 && (dist[u] < dist[heap[j = i / 2]] || (dist[u] == dist[heap[j]] && parent_kk[u] < parent_kk[heap[j]]))) {
        heap[iq[heap[j]] = i] = heap[j];
        i = j;
    }
    index_in_heap[u] = i;
    heap[i] = u;
}

void heapify_down(int u) {
    int i = index_in_heap[u], j;
    while ((j = get_next_index(i)) && (dist[heap[j]] < dist[u] || (dist[heap[j]] == dist[u] && parent_kk[heap[j]] < parent_kk[u]))) {
        heap[iq[heap[j]] = i] = heap[j];
        i = j;
    }
    index_in_heap[u] = i;
    heap[i] = u;
}

void push(int u) {
    index_in_heap[u] = ++heap_size;
    heapify_up(u);
}

int pop() {
    int u = heap[1], v = heap[heap_size--];
    index_in_heap[v] = 1;
    heapify_down(v);
    return u;
}

struct Edge {
    Edge *next;
    int j;
};

Edge adj[MAXN], adj_[N_];

void add_edge(int i, int j) {
    static Edge pool[M * 2], *ptr = pool;
    ptr->j = j;
    ptr->next = adj[i].next;
    adj[i].next = ptr++;
}

void add_edge_(int i, int h) {
    static Edge pool_[M_ * 2], *ptr = pool_;
    ptr->j = h;
    ptr->next = adj_[i].next;
    adj_[i].next = ptr++;
}

int n_, m_;
int u_list[M_], v_list[M_], uv_list[M_], cost[M_], cost_[M_];
int capacity[M_ * 2];

void connect(int u, int v, int cap, int cst) {
    int h = m_++;
    u_list[h] = u; v_list[h] = v; uv_list[h] = u ^ v; cost[h] = cst;
    capacity[h << 1] = cap; add_edge_(u, h << 1); add_edge_(v, h << 1 ^ 1);
}

void dijkstra(int s) {
    std::fill(dist, dist + n_, INF);
    dist[s] = 0;
    push(s);
    while (heap_size) {
        int u = pop();
        for (Edge *l = adj_[u].next; l; l = l->next) {
            int h_ = l->j, h = h_ >> 1, v = u ^ uv_list[h], p;
            if (capacity[h_]) {
                p = dist[u] + ((h_ & 1) == 0 ? cost[h] : -cost[h]);
                if (dist[v] == INF) {
                    dist[v] = p;
                    parent_kk[v] = parent_kk[u] + 1;
                    parent_bb[v] = h_;
                    push(v);
                } else if (dist[v] > p || (dist[v] == p && parent_kk[v] > parent_kk[u] + 1)) {
                    dist[v] = p;
                    parent_kk[v] = parent_kk[u] + 1;
                    parent_bb[v] = h_;
                    heapify_up(v);
                }
            }
        }
    }
}

void augment(int s, int t) {
    for (int u = t; u != s; u ^= uv_list[parent_bb[u]]) {
        int h_ = parent_bb[u], h = h_ >> 1;
        capacity[h_]--;
        capacity[h_ ^ 1]++;
    }
}

int max_flow(int s, int t) {
    std::memcpy(cost_, cost, sizeof(cost));
    while (true) {
        dijkstra(s);
        if (dist[t] == INF) break;
        augment(s, t);
        for (int h = 0; h < m_; h++) {
            int u = u_list[h], v = v_list[h];
            if (dist[u] != INF && dist[v] != INF) {
                cost_[h] += dist[u] - dist[v];
            }
        }
    }
    int total = 0;
    for (int h = 0; h < m_; h++) {
        total += cost[h] * capacity[h << 1];
    }
    return total;
}

int main() {
    int ii[MAXK];
    int n, m, k, c, d;
    std::cin >> n >> m >> k >> c >> d;
    for (int h = 0; h < k; h++) {
        std::cin >> ii[h];
        ii[h]--;
    }
    for (int h = 0; h < m; h++) {
        int i, j;
        std::cin >> i >> j;
        i--; j--;
        add_edge(i, j);
        add_edge(j, i);
    }
    int t = n + k + 1;
    n_ = n * t + 1;
    m_ = 0;
    for (int i = 0; i < n; i++) {
        for (int s = 0; s < t - 1; s++) {
            int u = i * t + s;
            for (Edge *l = adj[i].next; l; l = l->next) {
                int j = l->j;
                int v = j * t + s + 1;
                for (int x = 1; x <= k; x++) {
                    connect(u, v, 1, c + (x * 2 - 1) * d);
                }
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int s = 0; s < t - 1; s++) {
            int u = i * t + s, v = u + 1;
            connect(u, v, k, i == 0 ? 0 : c);
        }
    }
    for (int h = 0; h < k; h++) {
        connect(n_ - 1, ii[h] * t + 0, 1, 0);
    }
    std::cout << max_flow(n_ - 1, 0 * t + t - 1) << "\n";
    return 0;
}
